    37	        Imm_out_ID, rs1_data_ID, rs2_data_ID, addA_ID;
    38	    
    39	    wire reg_DE_flush, isFlushed_EXE, RegWrite_EXE, mem_w_EXE, mem_r_EXE,
    40	        ALUSrc_A_EXE, ALUSrc_B_EXE, ALUzero_EXE, ALUoverflow_EXE, DatatoReg_EXE,
    41	        csr_rw_EXE, csr_w_imm_mux_EXE, mret_EXE;
    42	    wire[1:0] exp_vector_EXE;
    43	    wire[2:0] u_b_h_w_EXE;
    44	    wire[3:0] ALUControl_EXE;
    45	    wire[4:0] rs1_EXE, rs2_EXE, rd_EXE;
    46	    wire[31:0] ALUout_EXE, PC_EXE, inst_EXE, rs1_data_EXE, rs2_data_EXE, Imm_EXE,
    47	        ALUA_EXE, ALUB_EXE, Dataout_EXE;
    48	
    49	    wire redirect_mux_exp, reg_FD_flush_exp, reg_DE_flush_exp,
    50	        reg_EM_flush_exp, reg_MW_flush_exp, RegWrite_cancel_exp, MemWrite_cancel_exp;
    51	    wire[31:0] PC_redirect_exp;
    52	    
    53	    wire isFlushed_MEM, RegWrite_MEM, DatatoReg_MEM, mem_w_MEM, mem_r_MEM,
    54	        csr_rw_MEM, csr_w_imm_mux_MEM, mret_MEM, l_access_fault_MEM, s_access_fault_MEM;
    55	    wire[1:0] exp_vector_MEM;
    56	    wire[2:0] u_b_h_w_MEM;
    57	    wire[4:0] rs1_MEM, rd_MEM;
    58	    wire[31:0] ALUout_MEM, PC_MEM, inst_MEM, Dataout_MEM, Datain_MEM,
    59	        rs1_data_MEM, CSRout_MEM, RAMout_MEM;
    60	
    61	
    62	    wire isFlushed_WB, RegWrite_WB, DatatoReg_WB;
    63	    wire[3:0] exp_vector_WB;
    64	    wire[4:0] rd_WB;
    65	    wire [31:0] wt_data_WB, PC_WB, inst_WB, ALUout_WB, Datain_WB;
    66	
    67	
    68	    // IF
    69		REG32 REG_PC(.clk(debug_clk),.rst(rst),.CE(PC_EN_IF),.D(final_PC_IF),.Q(PC_IF));
    70	    
    71	    add_32 add_IF(.a(PC_IF),.b(32'd4),.c(PC_4_IF));
    72	
    73	    // TODO: implement — PC select MUX (select between PC+4 and branch target)
    74	    MUX2T1_32 mux_IF(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(next_PC_IF));
    75	
    76	    // TODO: implement — exception redirect MUX (select between normal next_PC and exception redirect PC)
    77	    MUX2T1_32 redirectPC(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(final_PC_IF));
    78	
    79	    ROM_D inst_rom(.a(PC_IF[8:2]),.spo(inst_IF));
    80	
    81	
    82	    // ID
    83	    REG_IF_ID reg_IF_ID(.clk(debug_clk),.rst(rst),.EN(1'b1),.Data_stall(reg_FD_stall),
    84	        .flush(reg_FD_flush | reg_FD_flush_exp),.PCOUT(PC_IF),.IR(inst_IF),
    85	
    86	        .IR_ID(inst_ID),.PCurrent_ID(PC_ID),.isFlushed(isFlushed_ID));
    87	    
    88	    CtrlUnit ctrl(.inst(inst_ID),.cmp_res(cmp_res_ID),.Branch(Branch_ctrl),.ALUSrc_A(ALUSrc_A_ctrl),
    89	        .ALUSrc_B(ALUSrc_B_ctrl),.DatatoReg(DatatoReg_ctrl),.RegWrite(RegWrite_ctrl),
    90	        .mem_w(mem_w_ctrl),.mem_r(mem_r_ctrl),.rs1use(rs1use_ctrl),.rs2use(rs2use_ctrl),
    91	        .hazard_optype(hazard_optype_ctrl),.ImmSel(ImmSel_ctrl),.cmp_ctrl(cmp_ctrl),
    92	        .ALUControl(ALUControl_ctrl),.JALR(JALR),.MRET(MRET),.csr_rw(csr_rw_ctrl),
    93	        .csr_w_imm_mux(csr_w_imm_mux_ctrl),.exp_vector(exp_vector_ctrl));
    94	    
    95	    Regs register(.clk(debug_clk),.rst(rst),.L_S(RegWrite_WB & ~RegWrite_cancel_exp),
    96	        .R_addr_A(inst_ID[19:15]),.R_addr_B(inst_ID[24:20]),
    97	        .rdata_A(rs1_data_reg),.rdata_B(rs2_data_reg),
    98	        .Wt_addr(rd_WB),.Wt_data(wt_data_WB),
    99	        .Debug_addr(debug_addr[4:0]),.Debug_regs(Debug_regs));
   100	    
   101	    ImmGen imm_gen(.ImmSel(ImmSel_ctrl),.inst_field(inst_ID),.Imm_out(Imm_out_ID));
   102	    
   103	    // TODO: implement — forwarding MUX A (select between reg data, EXE bypass, MEM bypass, MEM load data)
   104	    MUX4T1_32 mux_forward_A(.I0(32'b0),.I1(32'b0),.I2(32'b0),.I3(32'b0),
   105	        .s(2'b0),.o(rs1_data_ID));
   106	    
   107	    // TODO: implement — forwarding MUX B (select between reg data, EXE bypass, MEM bypass, MEM load data)
   108	    MUX4T1_32 mux_forward_B(.I0(32'b0),.I1(32'b0),.I2(32'b0),.I3(32'b0),
   109	        .s(2'b0),.o(rs2_data_ID));
   110	    
   111	    // TODO: implement — branch base address MUX (select between PC and rs1 for JALR)
   112	    MUX2T1_32 mux_branch_ID(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(addA_ID));
   113	
   114	    add_32 add_branch_ID(.a(addA_ID),.b(Imm_out_ID),.c(jump_PC_ID));
   115	
   116	    cmp_32 cmp_ID(.a(rs1_data_ID),.b(rs2_data_ID),.ctrl(cmp_ctrl),.c(cmp_res_ID));
   117	    
   118	    HazardDetectionUnit hazard_unit(.clk(debug_clk),.Branch_ID(Branch_ctrl),.rs1use_ID(rs1use_ctrl),
   119	        .rs2use_ID(rs2use_ctrl),.hazard_optype_ID(hazard_optype_ctrl),.rd_EXE(rd_EXE),
   120	        .rd_MEM(rd_MEM),.rs1_ID(inst_ID[19:15]),.rs2_ID(inst_ID[24:20]),.rs2_EXE(rs2_EXE),
   121	        .PC_EN_IF(PC_EN_IF),.reg_FD_stall(reg_FD_stall),.reg_FD_flush(reg_FD_flush),
   122	        .reg_DE_flush(reg_DE_flush),.forward_ctrl_ls(forward_ctrl_ls),.forward_ctrl_A(forward_ctrl_A),
   123	        .forward_ctrl_B(forward_ctrl_B));
   124	
   125	
   126	    // EX
   127	    REG_ID_EX reg_ID_EX(.clk(debug_clk),.rst(rst),.EN(1'b1),
   128	        .flush(reg_DE_flush | reg_DE_flush_exp | isFlushed_ID),
   129	        .IR_ID(inst_ID),.PCurrent_ID(PC_ID),.rs1_addr(inst_ID[19:15]),.rs2_addr(inst_ID[24:20]),
   130	        .rs1_data(rs1_data_ID),.rs2_data(rs2_data_ID),.Imm32(Imm_out_ID),.rd_addr(inst_ID[11:7]),
   131	        .ALUSrc_A(ALUSrc_A_ctrl),.ALUSrc_B(ALUSrc_B_ctrl),.ALUC(ALUControl_ctrl),.DatatoReg(DatatoReg_ctrl),
   132	        .RegWrite(RegWrite_ctrl),.WR(mem_w_ctrl),.u_b_h_w(inst_ID[14:12]),.mem_r(mem_r_ctrl),
   133	        .csr_rw(csr_rw_ctrl),.csr_w_imm_mux(csr_w_imm_mux_ctrl),.mret(MRET),
   134	        .exp_vector(exp_vector_ctrl),
   135	
   136	        .PCurrent_EX(PC_EXE),.IR_EX(inst_EXE),.rs1_EX(rs1_EXE),.rs2_EX(rs2_EXE),
   137	        .A_EX(rs1_data_EXE),.B_EX(rs2_data_EXE),.Imm32_EX(Imm_EXE),.rd_EX(rd_EXE),
   138	        .ALUSrc_A_EX(ALUSrc_A_EXE),.ALUSrc_B_EX(ALUSrc_B_EXE),.ALUC_EX(ALUControl_EXE),
   139	        .DatatoReg_EX(DatatoReg_EXE),.RegWrite_EX(RegWrite_EXE),.WR_EX(mem_w_EXE),
   140	        .u_b_h_w_EX(u_b_h_w_EXE),.mem_r_EX(mem_r_EXE),.isFlushed(isFlushed_EXE),
   141	        .csr_rw_EX(csr_rw_EXE),.csr_w_imm_mux_EX(csr_w_imm_mux_EXE),.mret_EX(mret_EXE),
   142	        .exp_vector_EX(exp_vector_EXE));
   143	    
   144	    // TODO: implement — ALU source A MUX (select between rs1_data and PC)
   145	    MUX2T1_32 mux_A_EXE(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(ALUA_EXE));
   146	
   147	    // TODO: implement — ALU source B MUX (select between rs2_data and immediate)
   148	    MUX2T1_32 mux_B_EXE(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(ALUB_EXE));
   149	
   150	    ALU alu(.A(ALUA_EXE),.B(ALUB_EXE),.Control(ALUControl_EXE),
   151	        .res(ALUout_EXE),.zero(ALUzero_EXE),.overflow(ALUoverflow_EXE));
   152	    
   153	    // TODO: implement — load-store forwarding MUX (select between rs2_data and MEM load data)
   154	    MUX2T1_32 mux_forward_EXE(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(Dataout_EXE));
   155	
   156	
   157	    // MEM
   158	    REG_EX_MEM reg_EXE_MEM(.clk(debug_clk),.rst(rst),.EN(1'b1),.flush(reg_EM_flush_exp | isFlushed_EXE),
   159	        .IR_EX(inst_EXE),.PCurrent_EX(PC_EXE),.ALUO_EX(ALUout_EXE),.B_EX(Dataout_EXE),
   160	        .rd_EX(rd_EXE),.rs1_EX(rs1_EXE),.rs1_data_EX(rs1_data_EXE),.DatatoReg_EX(DatatoReg_EXE),
   161	        .RegWrite_EX(RegWrite_EXE),.WR_EX(mem_w_EXE),.u_b_h_w_EX(u_b_h_w_EXE),.mem_r_EX(mem_r_EXE),
   162	        .csr_rw_EX(csr_rw_EXE),.csr_w_imm_mux_EX(csr_w_imm_mux_EXE),.mret_EX(mret_EXE),
   163	        .exp_vector_EX(exp_vector_EXE),
   164	
   165	        .PCurrent_MEM(PC_MEM),.IR_MEM(inst_MEM),.ALUO_MEM(ALUout_MEM),.Datao_MEM(Dataout_MEM),
   166	        .rd_MEM(rd_MEM),.rs1_MEM(rs1_MEM),.rs1_data_MEM(rs1_data_MEM),.DatatoReg_MEM(DatatoReg_MEM),
   167	        .RegWrite_MEM(RegWrite_MEM),.WR_MEM(mem_w_MEM),.u_b_h_w_MEM(u_b_h_w_MEM),.mem_r_MEM(mem_r_MEM),
   168	        .isFlushed(isFlushed_MEM),.csr_rw_MEM(csr_rw_MEM),.csr_w_imm_mux_MEM(csr_w_imm_mux_MEM),
   169	        .mret_MEM(mret_MEM),.exp_vector_MEM(exp_vector_MEM));
   170	    
   171	    RAM_B data_ram(.addra(ALUout_MEM),.clka(debug_clk),.dina(Dataout_MEM), 
   172	        .wea(mem_w_MEM & ~MemWrite_cancel_exp),.rea(mem_r_MEM),.douta(RAMout_MEM),.mem_u_b_h_w(u_b_h_w_MEM),
   173	        .l_access_fault(l_access_fault_MEM),.s_access_fault(s_access_fault_MEM));
   174	
   175	    ExceptionUnit exp_unit(.clk(debug_clk),.rst(rst),.csr_rw_in(csr_rw_MEM),.csr_wsc_mode_in(inst_MEM[13:12]),
   176	        .csr_w_imm_mux(csr_w_imm_mux_MEM),.csr_rw_addr_in(inst_MEM[31:20]),
   177	        .csr_w_data_reg(rs1_data_MEM),.csr_w_data_imm(rs1_MEM),
   178	        .csr_r_data_out(CSRout_MEM),
   179	
   180	        .interrupt(interrupter),
   181	        .illegal_inst(~isFlushed_WB & exp_vector_WB[3]),
   182	        .ecall_m(~isFlushed_WB & exp_vector_WB[2]),
   183	        .l_access_fault(~isFlushed_WB & exp_vector_WB[1]),
   184	        .s_access_fault(~isFlushed_WB & exp_vector_WB[0]),
   185	        .mret(mret_MEM),
   186	        
   187	        .epc_cur(PC_WB),
   188	        .epc_next(~isFlushed_MEM ? PC_MEM : ~isFlushed_EXE ? PC_EXE :
   189	        ~isFlushed_ID ? PC_ID : PC_IF),
   190	        .PC_redirect(PC_redirect_exp),.redirect_mux(redirect_mux_exp),
   191	        .reg_FD_flush(reg_FD_flush_exp),.reg_DE_flush(reg_DE_flush_exp),
   192	        .reg_EM_flush(reg_EM_flush_exp),.reg_MW_flush(reg_MW_flush_exp),
   193	        .RegWrite_cancel(RegWrite_cancel_exp),.MemWrite_cancel(MemWrite_cancel_exp));
   194	    
   195	    // TODO: implement — CSR output MUX (select between RAM output and CSR output)
   196	    MUX2T1_32 mux_csrout(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(Datain_MEM));
   197	        
   198	
   199	    // WB
   200	    REG_MEM_WB reg_MEM_WB(.clk(debug_clk),.rst(rst),.EN(1'b1),.flush(reg_MW_flush_exp | isFlushed_MEM),
   201	        .IR_MEM(inst_MEM),.PCurrent_MEM(PC_MEM),.ALUO_MEM(ALUout_MEM),.Datai(Datain_MEM),
   202	        .rd_MEM(rd_MEM),.DatatoReg_MEM(DatatoReg_MEM),.RegWrite_MEM(RegWrite_MEM),
   203	        .exp_vector_MEM({exp_vector_MEM, l_access_fault_MEM, s_access_fault_MEM}),
   204	
   205	        .PCurrent_WB(PC_WB),.IR_WB(inst_WB),.ALUO_WB(ALUout_WB),.MDR_WB(Datain_WB),
   206	        .rd_WB(rd_WB),.DatatoReg_WB(DatatoReg_WB),.RegWrite_WB(RegWrite_WB),
   207	        .isFlushed(isFlushed_WB),.exp_vector_WB(exp_vector_WB));
   208	    
   209	    // TODO: implement — write-back MUX (select between ALU result and memory/CSR data)
   210	    MUX2T1_32 mux_WB(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(wt_data_WB));
   211	
   212	    assign wb_inst = inst_WB;
   213	    assign wb_pc = PC_WB;
   214	    assign mem_addr = (mem_r_MEM | mem_w_MEM) ? ALUout_MEM : 32'hFFFFFFFF ;
   215	    assign mem_data = (mem_r_MEM | mem_w_MEM) ? Datain_MEM : 32'hAA55AA55 ;
   216	
   217		assign debug_data = Debug_regs;
   218	
   219	endmodule
===== core/CtrlUnit.v =====
     1	`timescale 1ns / 1ps
     2	
     3	
     4	module CtrlUnit(
     5	    input[31:0] inst,
     6	    input cmp_res,
     7	    output Branch, ALUSrc_A, ALUSrc_B, DatatoReg, RegWrite, mem_w,
     8	        mem_r, rs1use, rs2use,
     9	    output [1:0] hazard_optype,
    10	    output [2:0] ImmSel, cmp_ctrl,
    11	    output [3:0] ALUControl,
    12	    output JALR, MRET,
    13	
    14	    output csr_rw, csr_w_imm_mux,
    15	
    16	    output[1:0] exp_vector
    17	);
    18	
    19	    wire[6:0] funct7 = inst[31:25];
    20	    wire[2:0] funct3 = inst[14:12];
    21	    wire[6:0] opcode = inst[6:0];
    22	
    23	    wire Rop = opcode == 7'b0110011;
    24	    wire Iop = opcode == 7'b0010011;
    25	    wire Bop = opcode == 7'b1100011;
    26	    wire Lop = opcode == 7'b0000011;
    27	    wire Sop = opcode == 7'b0100011;
    28	    wire CSRop = opcode == 7'b1110011;
    29	
    30	    wire funct7_0  = funct7 == 7'h0;
    31	    wire funct7_32 = funct7 == 7'h20;
    32	
    33	    wire funct3_0 = funct3 == 3'h0;
    34	    wire funct3_1 = funct3 == 3'h1;
    35	    wire funct3_2 = funct3 == 3'h2;
    36	    wire funct3_3 = funct3 == 3'h3;
    37	    wire funct3_4 = funct3 == 3'h4;
    38	    wire funct3_5 = funct3 == 3'h5;
    39	    wire funct3_6 = funct3 == 3'h6;
    40	    wire funct3_7 = funct3 == 3'h7;
    41	
    42	    wire ADD  = Rop & funct3_0 & funct7_0;
    43	    wire SUB  = Rop & funct3_0 & funct7_32;
    44	    wire SLL  = Rop & funct3_1 & funct7_0;
    45	    wire SLT  = Rop & funct3_2 & funct7_0;
    46	    wire SLTU = Rop & funct3_3 & funct7_0;
    47	    wire XOR  = Rop & funct3_4 & funct7_0;
    48	    wire SRL  = Rop & funct3_5 & funct7_0;
    49	    wire SRA  = Rop & funct3_5 & funct7_32;
    50	    wire OR   = Rop & funct3_6 & funct7_0;
    51	    wire AND  = Rop & funct3_7 & funct7_0;
    52	
    53	    wire ADDI  = Iop & funct3_0;	
    54	    wire SLTI  = Iop & funct3_2;
    55	    wire SLTIU = Iop & funct3_3;
    56	    wire XORI  = Iop & funct3_4;
    57	    wire ORI   = Iop & funct3_6;
    58	    wire ANDI  = Iop & funct3_7;
    59	    wire SLLI  = Iop & funct3_1 & funct7_0;
    60	    wire SRLI  = Iop & funct3_5 & funct7_0;
    61	    wire SRAI  = Iop & funct3_5 & funct7_32;
    62	
    63	    wire BEQ = Bop & funct3_0;
    64	    wire BNE = Bop & funct3_1;
    65	    wire BLT = Bop & funct3_4;
    66	    wire BGE = Bop & funct3_5;
    67	    wire BLTU = Bop & funct3_6;
    68	    wire BGEU = Bop & funct3_7;
    69	
    70	    wire LB =  Lop & funct3_0;
    71	    wire LH =  Lop & funct3_1;
    72	    wire LW =  Lop & funct3_2;
    73	    wire LBU = Lop & funct3_4;
    74	    wire LHU = Lop & funct3_5;
    75	
    76	    wire SB = Sop & funct3_0;
    77	    wire SH = Sop & funct3_1;
    78	    wire SW = Sop & funct3_2;
    79	
    80	    wire LUI   = opcode == 7'b0110111;
    81	    wire AUIPC = opcode == 7'b0010111;
    82	
    83	    wire JAL  =  opcode == 7'b1101111;
    84	    assign JALR = (opcode == 7'b1100111) && funct3_0;
    85	
    86	    wire CSRRW = CSRop & funct3_1;
    87	    wire CSRRS = CSRop & funct3_2;
    88	    wire CSRRC = CSRop & funct3_3;
    89	    wire CSRRWI = CSRop & funct3_5;
    90	    wire CSRRSI = CSRop & funct3_6;
    91	    wire CSRRCI = CSRop & funct3_7;
    92	
    93	    assign MRET = inst == 32'b0011000_00010_00000_000_00000_1110011;
    94	    wire ECALL = inst == 32'b0111_0011;
    95	
    96	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU;
    97	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
    98	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
    99	    wire L_valid = LW | LH | LB | LHU | LBU;
   100	    wire S_valid = SW | SH | SB;
   101	    wire CSR_valid = CSRRW | CSRRS | CSRRC | CSRRWI | CSRRSI | CSRRCI;
   102	
   103	
   104	    // TODO: implement — generate control signals based on decoded instruction
   105	    assign Branch = 0;
   106	    assign ImmSel = 3'b0;
   107	    assign cmp_ctrl = 3'b0;
   108	    assign ALUSrc_A = 0;
   109	    assign ALUSrc_B = 0;
   110	    assign ALUControl = 4'b0;
   111	    assign DatatoReg = 0;
   112	    assign RegWrite = 0;
   113	    assign mem_w = 0;
   114	    assign mem_r = 0;
   115	    assign rs1use = 0;
   116	    assign rs2use = 0;
   117	    assign hazard_optype = 2'b0;
   118	
   119	    // TODO: implement — CSR control signal generation
   120	    assign csr_rw = 0;
   121	    assign csr_w_imm_mux = 0;
   122	    assign exp_vector = 2'b0;
   123	
   124	endmodule===== core/ALU.v =====
     1	`timescale 1ns / 1ps
     2	
     3	module ALU(
     4	    input[31:0] A, B,
