285	module CtrlUnit(
286	    input[31:0] inst,
287	    input cmp_res,
288	    output Branch, ALUSrc_A, ALUSrc_B, DatatoReg, RegWrite, mem_w,
289	        mem_r, rs1use, rs2use,
290	    output [1:0] hazard_optype,
291	    output [2:0] ImmSel, cmp_ctrl,
292	    output [3:0] ALUControl,
293	    output JALR, MRET,
294	
295	    output csr_rw, csr_w_imm_mux,
296	
297	    output[1:0] exp_vector
298	);
299	
300	    wire[6:0] funct7 = inst[31:25];
301	    wire[2:0] funct3 = inst[14:12];
302	    wire[6:0] opcode = inst[6:0];
303	
304	    wire Rop = opcode == 7'b0110011;
305	    wire Iop = opcode == 7'b0010011;
306	    wire Bop = opcode == 7'b1100011;
307	    wire Lop = opcode == 7'b0000011;
308	    wire Sop = opcode == 7'b0100011;
309	    wire CSRop = opcode == 7'b1110011;
310	
311	    wire funct7_0  = funct7 == 7'h0;
312	    wire funct7_32 = funct7 == 7'h20;
313	
314	    wire funct3_0 = funct3 == 3'h0;
315	    wire funct3_1 = funct3 == 3'h1;
316	    wire funct3_2 = funct3 == 3'h2;
317	    wire funct3_3 = funct3 == 3'h3;
318	    wire funct3_4 = funct3 == 3'h4;
319	    wire funct3_5 = funct3 == 3'h5;
320	    wire funct3_6 = funct3 == 3'h6;
321	    wire funct3_7 = funct3 == 3'h7;
322	
323	    wire ADD  = Rop & funct3_0 & funct7_0;
324	    wire SUB  = Rop & funct3_0 & funct7_32;
325	    wire SLL  = Rop & funct3_1 & funct7_0;
326	    wire SLT  = Rop & funct3_2 & funct7_0;
327	    wire SLTU = Rop & funct3_3 & funct7_0;
328	    wire XOR  = Rop & funct3_4 & funct7_0;
329	    wire SRL  = Rop & funct3_5 & funct7_0;
330	    wire SRA  = Rop & funct3_5 & funct7_32;
331	    wire OR   = Rop & funct3_6 & funct7_0;
332	    wire AND  = Rop & funct3_7 & funct7_0;
333	
334	    wire ADDI  = Iop & funct3_0;	
335	    wire SLTI  = Iop & funct3_2;
336	    wire SLTIU = Iop & funct3_3;
337	    wire XORI  = Iop & funct3_4;
338	    wire ORI   = Iop & funct3_6;
339	    wire ANDI  = Iop & funct3_7;
340	    wire SLLI  = Iop & funct3_1 & funct7_0;
341	    wire SRLI  = Iop & funct3_5 & funct7_0;
342	    wire SRAI  = Iop & funct3_5 & funct7_32;
343	
344	    wire BEQ = Bop & funct3_0;
345	    wire BNE = Bop & funct3_1;
346	    wire BLT = Bop & funct3_4;
347	    wire BGE = Bop & funct3_5;
348	    wire BLTU = Bop & funct3_6;
349	    wire BGEU = Bop & funct3_7;
350	
351	    wire LB =  Lop & funct3_0;
352	    wire LH =  Lop & funct3_1;
353	    wire LW =  Lop & funct3_2;
354	    wire LBU = Lop & funct3_4;
355	    wire LHU = Lop & funct3_5;
356	
357	    wire SB = Sop & funct3_0;
358	    wire SH = Sop & funct3_1;
359	    wire SW = Sop & funct3_2;
360	
361	    wire LUI   = opcode == 7'b0110111;
362	    wire AUIPC = opcode == 7'b0010111;
363	
364	    wire JAL  =  opcode == 7'b1101111;
365	    assign JALR = (opcode == 7'b1100111) && funct3_0;
366	
367	    wire CSRRW = CSRop & funct3_1;
368	    wire CSRRS = CSRop & funct3_2;
369	    wire CSRRC = CSRop & funct3_3;
370	    wire CSRRWI = CSRop & funct3_5;
371	    wire CSRRSI = CSRop & funct3_6;
372	    wire CSRRCI = CSRop & funct3_7;
373	
374	    assign MRET = inst == 32'b0011000_00010_00000_000_00000_1110011;
375	    wire ECALL = inst == 32'b0111_0011;
376	
377	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU;
378	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
379	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
380	    wire L_valid = LW | LH | LB | LHU | LBU;
381	    wire S_valid = SW | SH | SB;
382	    wire CSR_valid = CSRRW | CSRRS | CSRRC | CSRRWI | CSRRSI | CSRRCI;
383	
384	
385	    // 实现：条件分支成立或无条件跳转时置位 Branch
386	    assign Branch = B_valid & cmp_res | JAL | JALR;
387	
388	    localparam Imm_type_I = 3'b001;
389	    localparam Imm_type_B = 3'b010;
390	    localparam Imm_type_J = 3'b011;
391	    localparam Imm_type_S = 3'b100;
392	    localparam Imm_type_U = 3'b101;
393	    // 实现：根据指令类型选择立即数格式
394	    assign ImmSel = {3{I_valid | L_valid | JALR}} & Imm_type_I |
395	                    {3{B_valid}}                 & Imm_type_B |
396	                    {3{JAL}}                     & Imm_type_J |
397	                    {3{S_valid}}                 & Imm_type_S |
398	                    {3{LUI | AUIPC}}             & Imm_type_U ;
399	
400	    localparam cmp_EQ  = 3'b001;
401	    localparam cmp_NE  = 3'b010;
402	    localparam cmp_LT  = 3'b011;
403	    localparam cmp_LTU = 3'b100;
404	    localparam cmp_GE  = 3'b101;
405	    localparam cmp_GEU = 3'b110;
406	    // 实现：根据分支子类型选择 cmp_32 的比较方式
407	    assign cmp_ctrl = {3{BEQ }} & cmp_EQ  |
408	                      {3{BNE }} & cmp_NE  |
409	                      {3{BLT }} & cmp_LT  |
410	                      {3{BLTU}} & cmp_LTU |
411	                      {3{BGE }} & cmp_GE  |
412	                      {3{BGEU}} & cmp_GEU ;
413	
414	    // 实现：AUIPC/JAL/JALR 使用 PC 作为 ALU 的 A 操作数
415	    assign ALUSrc_A = AUIPC | JAL | JALR;
416	
417	    // 实现：立即数类指令使用立即数作为 ALU 的 B 操作数
418	    assign ALUSrc_B = I_valid | L_valid | S_valid | LUI | AUIPC;
419	
420	    localparam ALU_ADD  = 4'b0001;
421	    localparam ALU_SUB  = 4'b0010;
422	    localparam ALU_AND  = 4'b0011;
423	    localparam ALU_OR   = 4'b0100;
424	    localparam ALU_XOR  = 4'b0101;
425	    localparam ALU_SLL  = 4'b0110;
426	    localparam ALU_SRL  = 4'b0111;
427	    localparam ALU_SLT  = 4'b1000;
428	    localparam ALU_SLTU = 4'b1001;
429	    localparam ALU_SRA  = 4'b1010;
430	    localparam ALU_Ap4  = 4'b1011;
431	    localparam ALU_Bout = 4'b1100;
432	    // 实现：根据指令类型产生 ALUControl
433	    assign ALUControl = {4{ADD  | ADDI  | L_valid | S_valid | AUIPC}} & ALU_ADD  |
434	                        {4{SUB }}                                     & ALU_SUB  |
435	                        {4{AND  | ANDI }}                             & ALU_AND  |
436	                        {4{OR   | ORI  }}                             & ALU_OR   |
437	                        {4{XOR  | XORI }}                             & ALU_XOR  |
438	                        {4{SLL  | SLLI }}                             & ALU_SLL  |
439	                        {4{SRL  | SRLI }}                             & ALU_SRL  |
440	                        {4{SLT  | SLTI }}                             & ALU_SLT  |
441	                        {4{SLTU | SLTIU}}                             & ALU_SLTU |
442	                        {4{SRA  | SRAI }}                             & ALU_SRA  |
443	                        {4{JAL  | JALR }}                             & ALU_Ap4  |
444	                        {4{LUI }}                                     & ALU_Bout ;
445	
446	    // 实现：DatatoReg, RegWrite, mem_w, mem_r, rs1use, rs2use
447	    assign DatatoReg = L_valid | CSR_valid;
448	    assign RegWrite  = R_valid | I_valid | L_valid | LUI | AUIPC | JAL | JALR | CSR_valid;
449	    assign mem_w     = S_valid;
450	    assign mem_r     = L_valid;
451	    assign rs1use    = R_valid | I_valid | L_valid | S_valid | B_valid | JALR |
452	                       CSRRW | CSRRS | CSRRC;
453	    assign rs2use    = R_valid | S_valid | B_valid;
454	
455	    localparam hazard_optype_ALU = 2'd1;
456	    localparam hazard_optype_LOAD = 2'd2;
457	    localparam hazard_optype_STORE = 2'd3;
458	    // 实现：hazard_optype —— load 为 2，其它写寄存器指令为 1，store 为 3，其余为 0
459	    assign hazard_optype = {2{L_valid}} & hazard_optype_LOAD  |
460	                           {2{S_valid}} & hazard_optype_STORE |
461	                           {2{R_valid | I_valid | LUI | AUIPC | JAL | JALR | CSR_valid}} & hazard_optype_ALU ;
462	
463	    // 实现：CSR 控制信号
464	    assign csr_rw        = CSR_valid;
465	    assign csr_w_imm_mux = CSRRWI | CSRRSI | CSRRCI;
466	
467	    // 实现：异常向量 {非法指令, ecall}
468	    wire inst_valid = R_valid | I_valid | B_valid | L_valid | S_valid |
469	                      LUI | AUIPC | JAL | JALR | CSR_valid | ECALL | MRET;
470	    assign exp_vector = {~inst_valid, ECALL};
471	
