475	module ALU(
476	    input[31:0] A, B,
477	    input[3:0] Control,
478	    output[31:0] res,
479	    output zero, overflow
480	);
481	
482	    localparam ALU_ADD  = 4'b0001;
483	    localparam ALU_SUB  = 4'b0010;
484	    localparam ALU_AND  = 4'b0011;
485	    localparam ALU_OR   = 4'b0100;
486	    localparam ALU_XOR  = 4'b0101;
487	    localparam ALU_SLL  = 4'b0110;
488	    localparam ALU_SRL  = 4'b0111;
489	    localparam ALU_SLT  = 4'b1000;
490	    localparam ALU_SLTU = 4'b1001;
491	    localparam ALU_SRA  = 4'b1010;
492	    localparam ALU_Ap4  = 4'b1011;
493	    localparam ALU_Bout = 4'b1100;
494	
495	    // 实现：根据 Control 选择运算，并生成 zero / overflow 标志
496	    // The ALU must support: ADD, SUB, AND, OR, XOR, SLL, SRL, SLT, SLTU, SRA, A+4, B-passthrough
497	    // Use the Control input to select which operation to perform.
498	    // zero should be 1 when res is all zeros.
499	    // overflow should be set for signed ADD/SUB overflow.
500	
501	    wire[31:0] res_ADD  = A + B;
502	    wire[31:0] res_SUB  = A - B;
503	    wire[31:0] res_AND  = A & B;
504	    wire[31:0] res_OR   = A | B;
505	    wire[31:0] res_XOR  = A ^ B;
506	    wire[31:0] res_SLL  = A << B[4:0];
507	    wire[31:0] res_SRL  = A >> B[4:0];
508	    wire[31:0] res_SRA  = $signed(A) >>> B[4:0];
509	    wire       res_lt   = $signed(A) < $signed(B);
510	    wire       res_ltu  = A < B;
511	    wire[31:0] res_SLT  = {31'b0, res_lt};
512	    wire[31:0] res_SLTU = {31'b0, res_ltu};
513	    wire[31:0] res_Ap4  = A + 32'd4;
514	    wire[31:0] res_Bout = B;
515	
516	    wire is_ADD  = Control == ALU_ADD ;
517	    wire is_SUB  = Control == ALU_SUB ;
518	    wire is_AND  = Control == ALU_AND ;
519	    wire is_OR   = Control == ALU_OR  ;
520	    wire is_XOR  = Control == ALU_XOR ;
521	    wire is_SLL  = Control == ALU_SLL ;
522	    wire is_SRL  = Control == ALU_SRL ;
523	    wire is_SLT  = Control == ALU_SLT ;
524	    wire is_SLTU = Control == ALU_SLTU;
525	    wire is_SRA  = Control == ALU_SRA ;
526	    wire is_Ap4  = Control == ALU_Ap4 ;
527	    wire is_Bout = Control == ALU_Bout;
528	
529	    assign res = {32{is_ADD }} & res_ADD  |
530	                 {32{is_SUB }} & res_SUB  |
531	                 {32{is_AND }} & res_AND  |
532	                 {32{is_OR  }} & res_OR   |
533	                 {32{is_XOR }} & res_XOR  |
534	                 {32{is_SLL }} & res_SLL  |
535	                 {32{is_SRL }} & res_SRL  |
536	                 {32{is_SLT }} & res_SLT  |
537	                 {32{is_SLTU}} & res_SLTU |
538	                 {32{is_SRA }} & res_SRA  |
539	                 {32{is_Ap4 }} & res_Ap4  |
540	                 {32{is_Bout}} & res_Bout ;
541	
542	    assign zero = ~(|res);
543	
544	    assign overflow = is_ADD  & (~(A[31] ^ B[31]) & (res_ADD[31] ^ A[31])) |
545	                      is_SUB  & ( (A[31] ^ B[31]) & (res_SUB[31] ^ A[31])) ;
546	
547	endmodule===== core/ImmGen.v =====
