549	
550	module ImmGen(
551	            input  wire [2:0] ImmSel,
552	            input  wire [31:0] inst_field,
553	            output[31:0] Imm_out
554	    );
555	    localparam Imm_type_I = 3'b001;
556	    localparam Imm_type_B = 3'b010;
557	    localparam Imm_type_J = 3'b011;
558	    localparam Imm_type_S = 3'b100;
559	    localparam Imm_type_U = 3'b101;
560	
561	    // 实现：根据 ImmSel 生成符号扩展后的立即数
562	    // Must handle I-type, B-type, J-type, S-type, and U-type immediate formats
563	    // following the RISC-V encoding specification.
564	    wire I = ImmSel == Imm_type_I;
565	    wire B = ImmSel == Imm_type_B;
566	    wire J = ImmSel == Imm_type_J;
567	    wire S = ImmSel == Imm_type_S;
568	    wire U = ImmSel == Imm_type_U;
569	
570	    wire[31:0] Imm_I = {{20{inst_field[31]}}, inst_field[31:20]};
571	    wire[31:0] Imm_B = {{20{inst_field[31]}}, inst_field[7], inst_field[30:25], inst_field[11:8], 1'b0};
572	    wire[31:0] Imm_J = {{12{inst_field[31]}}, inst_field[19:12], inst_field[20], inst_field[30:21], 1'b0};
573	    wire[31:0] Imm_S = {{20{inst_field[31]}}, inst_field[31:25], inst_field[11:7]};
574	    wire[31:0] Imm_U = {inst_field[31:12], 12'b0};
575	
576	    assign Imm_out = {32{I}} & Imm_I |
577	                     {32{B}} & Imm_B |
578	                     {32{J}} & Imm_J |
579	                     {32{S}} & Imm_S |
580	                     {32{U}} & Imm_U ;
581	endmodule
