604	module     Regs(input clk,
605					input rst,
606					input [4:0] R_addr_A, 
607					input [4:0] R_addr_B, 
608					input [4:0] Wt_addr, 
609					input [31:0]Wt_data, 
610					input L_S, 
611					output [31:0] rdata_A, 
612					output [31:0] rdata_B,
613					input [4:0] Debug_addr,         // debug address
614					output[31:0] Debug_regs        // debug data
615				  );
616	
617	reg [31:0] register [1:31]; 				// r1 - r31
618	integer i;
619	
620		// 实现：两读一写的寄存器堆
621		// - Reading two registers simultaneously (rdata_A, rdata_B)
622		// - Writing one register per cycle when L_S is asserted (write to Wt_addr with Wt_data)
623		// - x0 always reads as 0
624		// - Synchronous reset clears all registers to 0
625		// - Debug port reads register[Debug_addr] (0 if addr is 0)
626		assign rdata_A = (R_addr_A == 5'b0) ? 32'b0 : register[R_addr_A];	// read
627		assign rdata_B = (R_addr_B == 5'b0) ? 32'b0 : register[R_addr_B];	// read
628	
629		// 写口在时钟下降沿动作，使得同一周期 WB 写入的值可以被 ID 级立即读到
630		always @(negedge clk or posedge rst)
631		begin
632			if (rst) begin							// reset
633				for (i = 1; i < 32; i = i + 1)
634					register[i] <= 32'b0;
635			end
636			else begin
637				if ((Wt_addr != 5'b0) && (L_S == 1'b1))	// write
638					register[Wt_addr] <= Wt_data;
639			end
640		end
641	
642		assign Debug_regs = (Debug_addr == 5'b0) ? 32'b0 : register[Debug_addr];		//TEST
643	
644	endmodule
