647	===== core/RAM_B.v =====
648	`timescale 1ns / 1ps
649	
650	module RAM_B(
651	    input [31:0] addra,
652	    input clka,      // normal clock
653	    input[31:0] dina,
654	    input wea, 
655	    output[31:0] douta,
656	    output [7:0] sim_uart_char_out,
657	    output sim_uart_char_valid,
658	    input[2:0] mem_u_b_h_w
659	);
660	    localparam SIZE = 256;
661	    localparam ADDR_LINE = $clog2(SIZE);
662	    localparam SIM_UART_ADDR = 32'h10000000;
663	
664	    reg[7:0] data[0:SIZE-1];
665	
666	    initial	begin
667	        $readmemh("ram.mem", data);
668	    end
669	
670	    // 地址译码：数据存储器只占用低地址空间，取地址低 ADDR_LINE 位
671	    wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];
672	    wire is_uart   = (addra == SIM_UART_ADDR);
673	    wire word_op   = mem_u_b_h_w[1];
674	    wire half_op   = mem_u_b_h_w[0];
675	    wire unsigned_op = mem_u_b_h_w[2];
676	
677	    // 实现：按字节写入
678	    // Write byte/halfword/word based on mem_u_b_h_w control signals.
679	    // mem_u_b_h_w[1]=1 means word, mem_u_b_h_w[0]=1 means halfword, otherwise byte.
680	    // Only write when wea is asserted. SIM_UART_ADDR writes should be excluded.
681	    always @(posedge clka) begin
682	        if (wea & ~is_uart) begin
683	            if (word_op) begin
684	                data[addr]                          <= dina[7:0];
685	                data[(addr + 1) % SIZE]             <= dina[15:8];
686	                data[(addr + 2) % SIZE]             <= dina[23:16];
687	                data[(addr + 3) % SIZE]             <= dina[31:24];
688	            end
689	            else if (half_op) begin
690	                data[addr]                          <= dina[7:0];
691	                data[(addr + 1) % SIZE]             <= dina[15:8];
692	            end
693	            else begin
694	                data[addr]                          <= dina[7:0];
695	            end
696	        end
697	    end
698	
699	    // 实现：按字节读出并做符号/零扩展
700	    // Read byte/halfword/word based on mem_u_b_h_w.
701	    // mem_u_b_h_w[2]=1 means unsigned (zero-extend), otherwise sign-extend.
702	    // Return 0 if address is SIM_UART_ADDR.
703	    wire[31:0] rdata_w = {data[(addr + 3) % SIZE], data[(addr + 2) % SIZE],
704	                          data[(addr + 1) % SIZE], data[addr]};
705	    wire[15:0] rdata_h = {data[(addr + 1) % SIZE], data[addr]};
706	    wire[7:0]  rdata_b = data[addr];
707	
708	    assign douta = is_uart ? 32'b0 :
709	                   word_op ? rdata_w :
710	                   half_op ? (unsigned_op ? {16'b0, rdata_h} : {{16{rdata_h[15]}}, rdata_h}) :
711	                             (unsigned_op ? {24'b0, rdata_b} : {{24{rdata_b[7]}},  rdata_b}) ;
712	
713	    // 实现：串口模拟输出
714	    // Detect writes to SIM_UART_ADDR, latch character data, and output via sim_uart_char_out.
715	    reg[7:0] uart_char_reg;
716	    reg      uart_valid_reg;
717	
718	    initial begin
719	        uart_char_reg  = 8'b0;
720	        uart_valid_reg = 1'b0;
721	    end
722	
723	    always @(posedge clka) begin
724	        if (wea & is_uart) begin
725	            uart_char_reg  <= dina[7:0];
726	            uart_valid_reg <= 1'b1;
727	            // 仿真时直接把字符打印到控制台
728	            // synthesis translate_off
729	            $write("%c", dina[7:0]);
730	            // synthesis translate_on
731	        end
732	        else begin
733	            uart_valid_reg <= 1'b0;
734	        end
735	    end
736	
737	    assign sim_uart_char_valid = uart_valid_reg;
738	    assign sim_uart_char_out   = uart_char_reg;
739	endmodule===== core/HazardDetectionUnit.v =====
740	`timescale 1ps/1ps
741	
742	module HazardDetectionUnit(
743	    input clk,
744	    input Branch_ID, rs1use_ID, rs2use_ID,
745	    input[1:0] hazard_optype_ID,
746	    input[4:0] rd_EXE, rd_MEM, rs1_ID, rs2_ID, rs2_EXE,
747	    output PC_EN_IF, reg_FD_stall, reg_FD_flush, reg_DE_flush,
748	    output forward_ctrl_ls,
749	    output[1:0] forward_ctrl_A, forward_ctrl_B
750	);
751	
752	    reg[1:0] hazard_optype_EXE, hazard_optype_MEM;
753	    // 实现：把 ID 级的 hazard_optype 沿流水线打拍，跟踪 EXE / MEM 级指令的类型
754	
755	    localparam hazard_optype_ALU = 2'd1;
756	    localparam hazard_optype_LOAD = 2'd2;
757	    localparam hazard_optype_STORE = 2'd3;
758	
759	    // 实现：冒险检测与前递控制
760	    // Detect forwarding conditions for rs1 and rs2 against EXE and MEM stages.
761	    // Generate stall when load-use hazard is detected.
762	    // Generate forwarding selectors for ALU-to-ID and MEM-to-ID forwarding.
763	    // Generate load-store forwarding when store in EXE reads data produced by load in MEM.
764	
765	    initial begin
766	        hazard_optype_EXE = 2'd0;
767	        hazard_optype_MEM = 2'd0;
768	    end
769	
770	    // ID 级的读寄存器需求
771	    wire rs1_valid = rs1use_ID & (rs1_ID != 5'd0);
772	    wire rs2_valid = rs2use_ID & (rs2_ID != 5'd0);
773	
774	    // EXE / MEM 级指令是否会写回寄存器
775	    wire EXE_write = (hazard_optype_EXE == hazard_optype_ALU) |
776	                     (hazard_optype_EXE == hazard_optype_LOAD);
777	    wire MEM_write = (hazard_optype_MEM == hazard_optype_ALU) |
778	                     (hazard_optype_MEM == hazard_optype_LOAD);
779	
780	    wire EXE_is_load = hazard_optype_EXE == hazard_optype_LOAD;
781	    wire MEM_is_load = hazard_optype_MEM == hazard_optype_LOAD;
782	
783	    // 相关判断
784	    wire rs1_EXE_conflict = rs1_valid & EXE_write & (rs1_ID == rd_EXE);
785	    wire rs2_EXE_conflict = rs2_valid & EXE_write & (rs2_ID == rd_EXE);
786	    wire rs1_MEM_conflict = rs1_valid & MEM_write & (rs1_ID == rd_MEM);
787	    wire rs2_MEM_conflict = rs2_valid & MEM_write & (rs2_ID == rd_MEM);
788	
789	    // load-use 冒险：EXE 级是 load，ID 级需要它的结果 -> 必须暂停一拍。
790	    // 例外：ID 级是 store 且只有 rs2（写入的数据）相关时，可以等到 EXE/MEM 级
791	    //       再用 load-store 前递解决，不需要暂停。
792	    wire ID_is_store = hazard_optype_ID == hazard_optype_STORE;
793	    wire load_use_hazard = EXE_is_load &
794	                           (rs1_EXE_conflict | (rs2_EXE_conflict & ~ID_is_store));
795	
796	    assign reg_FD_stall = load_use_hazard;
797	    assign PC_EN_IF     = ~load_use_hazard;
798	    assign reg_DE_flush = load_use_hazard;            // 向 EXE 级插入气泡
799	    assign reg_FD_flush = Branch_ID & ~load_use_hazard;   // 跳转发生时清除已取的下一条指令
800	
801	    // 前递选择：00 = 寄存器堆, 01 = EXE 级 ALU 结果,
802	    //           10 = MEM 级 ALU 结果, 11 = MEM 级 load 数据
803	    assign forward_ctrl_A = rs1_EXE_conflict ? 2'b01 :
804	                            rs1_MEM_conflict ? (MEM_is_load ? 2'b11 : 2'b10) :
805	                            2'b00;
806	    assign forward_ctrl_B = rs2_EXE_conflict ? 2'b01 :
807	                            rs2_MEM_conflict ? (MEM_is_load ? 2'b11 : 2'b10) :
808	                            2'b00;
809	
810	    // load-store 前递：EXE 级的 store 要写的数据来自 MEM 级 load 的结果
811	    assign forward_ctrl_ls = (hazard_optype_EXE == hazard_optype_STORE) &
812	                             MEM_is_load & (rs2_EXE != 5'd0) & (rs2_EXE == rd_MEM);
813	
814	    always @(posedge clk) begin
815	        hazard_optype_EXE <= reg_DE_flush ? 2'd0 : hazard_optype_ID;
816	        hazard_optype_MEM <= hazard_optype_EXE;
817	    end
818	
819	endmodule
